def _safe_path(value: Any) -> str:
    if not isinstance(value, str) or not value:
        raise IncrementalStageError("manifest file path must be a non-empty string")
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or value != path.as_posix():
        raise IncrementalStageError(f"manifest file path is unsafe: {value!r}")
    return value

def _manifest_files(payload: Any) -> dict[str, dict[str, Any]]:
    if not isinstance(payload, dict) or not isinstance(payload.get("files"), list):
        raise IncrementalStageError("artifact manifest must contain files[]")
    files: dict[str, dict[str, Any]] = {}
    for row in payload["files"]:
        if not isinstance(row, dict):
            raise IncrementalStageError("artifact manifest files[] entries must be objects")
        path = _safe_path(row.get("path"))
        digest = row.get("sha256")
        if not isinstance(digest, str) or len(digest) != 64:
            raise IncrementalStageError(f"manifest sha256 is invalid for {path}")
        if path in files:
            raise IncrementalStageError(f"artifact manifest contains duplicate path: {path}")
        files[path] = row
    return files

def _load_local_manifest(bundle_dir: Path) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    manifest_path = bundle_dir / "artifact_manifest.json"
    try:
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise IncrementalStageError(f"cannot read local artifact manifest: {exc}") from exc
    files = _manifest_files(payload)
    for relative_path, row in files.items():
        source = bundle_dir / relative_path
        if not source.is_file():
            raise IncrementalStageError(f"local manifest path is missing: {relative_path}")
        actual = hashlib.sha256(source.read_bytes()).hexdigest()
        if actual != row["sha256"]:
            raise IncrementalStageError(f"local manifest digest mismatch: {relative_path}")
    if not (bundle_dir / "checksums.sha256").is_file():
        raise IncrementalStageError("local bundle is missing checksums.sha256")
    return payload, files

def verify(item: tuple[str, dict[str, Any]]) -> str:
    path, row = item
    try:
        body = fetcher(f"{base_url}/{path}")
    except Exception as exc:
        raise IncrementalStageError(
            f"remote artifact request failed for {path}: {exc}"
        ) from exc
    actual = hashlib.sha256(body).hexdigest()
    if actual != row["sha256"]:
        raise IncrementalStageError(f"remote artifact digest mismatch: {path}")
    return path

@dataclass(frozen=True)
class SpecNode:
    path: Path
    data: dict[str, Any]

    @property
    def id(self) -> str:
        return str(self.data.get("id", "")).strip()

    @property
    def title(self) -> str:
        return str(self.data.get("title", "")).strip()

    @property
    def status(self) -> str:
        return str(self.data.get("status", "stub")).strip()

    @property
    def gate_state(self) -> str:
        return str(self.data.get("gate_state", "none")).strip() or "none"

    @property
    def allowed_paths(self) -> list[str]:
        value = self.data.get("allowed_paths", [])
        return list(value) if isinstance(value, list) else []

def build_product_workspace_next_moves(
    workspace_root: Path,
    *,
    target_spec: str | None = None,
) -> dict[str, Any]:
    root = workspace_root.expanduser().resolve(strict=True)
    if not root.is_dir():
        raise ValueError(f"workspace root is not a directory: {root}")
    policy = load_policy()
    config_path = root / "specgraph.project.yaml"
    if not config_path.is_file():
        raise ValueError("product_workspace requires specgraph.project.yaml")
    project_policy = workspace.load_product_policy()
    environment = workspace.product_environment(config_path, project_policy)
    project = environment["project"]
    profile = project["governance_profile"]

    specs_dir = root / "specs" / "nodes"
    if not specs_dir.is_dir():
        raise ValueError("product_workspace requires specs/nodes directory")
    specs = workspace.load_specs_from_dir(specs_dir)
    if any(not isinstance(node.data, dict) for node in specs):
        raise ValueError("canonical spec nodes must be mappings with nonempty IDs")
    ids = [node.id for node in specs]
    if any(not node.id for node in specs):
        raise ValueError("canonical spec nodes must be mappings with nonempty IDs")
    if len(ids) != len(set(ids)):
        raise ValueError("canonical spec node IDs must be unique")
    for node in specs:
        if node.path.stem != node.id or node.data.get("kind") != "spec":
            raise ValueError(f"invalid canonical spec identity: {node.path.name}")

    if target_spec:
        target = next((node for node in specs if node.id == target_spec), None)
        if target is None:
            raise ValueError(f"target spec is absent from product workspace: {target_spec}")
        selected_specs = workspace.subtree_nodes(target, specs)
    else:
        selected_specs = specs

    gate_order = list(policy["priority"]["gates"])
    status_order = list(policy["priority"]["refinable_statuses"])
    if set(gate_order) != set(GATE_ACTIONS):
        raise ValueError("product next-move policy must rank every canonical gate state")
    authority = environment.get("supervisor_authority", {})
    refinement_allowed = (
        isinstance(authority, dict) and authority.get("allow_project_spec_refinement") is True
    )
    eligible: list[tuple[int, dict[str, Any]]] = []
    blocked: list[dict[str, Any]] = []
    for node in selected_specs:
        source_path = node.path.relative_to(root).as_posix()
        candidate = candidate_move(
            node,
            source_path=source_path,
            gate_order=gate_order,
            status_order=status_order,
        )
        if candidate is None:
            continue
        rank, move = candidate
        authorization = workspace.authorize_target(
            target_spec_id=node.id,
            target_paths=workspace.effective_allowed_paths_for_run(node, root),
            environment=environment,
        )
        blocked_by = list(authorization["blocked_by"])
        if not refinement_allowed:
            blocked_by.append("blocked_by_project_spec_refinement_disabled")
        if not blocked_by:
            eligible.append((rank, move))
        else:
            blocked.append(
                {
                    **move,
                    "command_hint": (
                        f"Resolve governance and workspace authority for {node.id} before action."
                    ),
                    "blocked_by": blocked_by,
                    "target_domain": authorization["target_domain"],
                }
            )
    eligible.sort(key=lambda entry: (entry[0], entry[1]["spec_id"]))
    blocked.sort(key=lambda move: move["spec_id"])
    recommended = eligible[0][1] if eligible else None
    current_scene = (
        ("refinement_ready" if recommended["kind"] == "refine_spec" else recommended["kind"])
        if recommended
        else "governance_blocked"
        if blocked
        else "steady_state"
    )

    return {
        "artifact_kind": "product_workspace_next_moves",
        "schema_version": 1,
        "generated_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "policy_reference": {
            "artifact_path": "tools/product_workspace_next_moves_policy.json",
            "sha256": file_digest(POLICY_PATH),
        },
        "project_environment_policy_reference": {
            "artifact_path": "tools/project_environment_policy.json",
            "sha256": file_digest(workspace.PROJECT_POLICY_PATH),
        },
        "project": {
            "project_id": project["project_id"],
            "governance_profile": profile,
        },
        "scope": {
            "target_spec": target_spec or "",
            "selected_spec_ids": [node.id for node in selected_specs],
            "selected_spec_count": len(selected_specs),
        },
        "input_contract": policy["input_contract"],
        "inputs": {
            "project_config": {
                "path": "specgraph.project.yaml",
                "sha256": file_digest(config_path),
            },
            "canonical_specs": [
                {
                    "path": node.path.relative_to(root).as_posix(),
                    "sha256": file_digest(node.path),
                }
                for node in specs
            ],
        },
        "current_scene": current_scene,
        "recommended_next_move_kind": recommended["kind"] if recommended else "none",
        "recommended_next_move": recommended,
        "alternatives": [move for _, move in eligible[1:]],
        "blocked_moves": blocked,
        "canonical_mutations_allowed": False,
        "tracked_artifacts_written": False,
    }

class BDDScenarioValuesSpec(BDDPolicy):
    rule_ref = "SG-RFC-0223.native.scenario-values"

    def skip_reason(self, context: BDDContext) -> str | None:
        return super().skip_reason(context) or entry_skip(context)

    def findings(self, context: BDDContext):
        findings = []
        for index, entry in enumerate(context.entries):
            if not entry.is_mapping:
                continue
            path = f"specification.bdd_scenarios[{index}]"
            if not entry.id.valid:
                findings.append(issue("invalid_value", path + ".id"))
            if not entry.steps_is_list or not entry.steps:
                findings.append(issue("invalid_value", path + ".steps"))
            else:
                findings.extend(
                    issue("invalid_value", f"{path}.steps[{i}]")
                    for i, step in enumerate(entry.steps)
                    if not step.valid
                )
        return tuple(findings)

class BDDPolicy(Specification[BDDContext]):
    spec_id = "SG-SPEC-0070"
    rule_ref: str

    def __init__(self) -> None:
        super().__init__(name=self.rule_ref)
        self._seal()

    def findings(self, context: BDDContext) -> tuple[BDDScenarioFinding, ...]:
        raise NotImplementedError

def load_native_bdd(source: str, *, profile: str, recorder=None) -> BDDResult:
    digest = sha256(source.encode("utf-8")).hexdigest()
    try:
        facts = context(load_yaml_text(source), profile)
    except (DuplicateKeyError, yaml.YAMLError, ValueError, TypeError) as error:
        code = "duplicate_yaml_key" if isinstance(error, DuplicateKeyError) else "invalid_value"
        if recorder is not None:
            for policy in POLICIES:
                recorder.skipped(policy.rule_ref)
        return BDDResult(
            profile,
            BDDScenarioPresence.INVALID,
            (issue(code, "document"),),
            tuple(PolicyOutcome(p.rule_ref, "skipped", "invalid_yaml_boundary") for p in POLICIES),
            (),
            digest,
            POLICIES[0].safe_trace_label(profile),
        )
    return evaluate(facts, digest, recorder=recorder)

def lint_file(path: Path) -> list[LintIssue]:
    issues: list[LintIssue] = []
    try:
        source = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return [LintIssue(path=path, message="file does not exist")]

    try:
        data = load_yaml_text(source)
    except Exception as exc:
        return [LintIssue(path=path, message=str(exc))]

    for message in _validate_spec_shape(data):
        issues.append(LintIssue(path=path, message=message))

    canonical = dump_canonical_yaml(data)
    if source != canonical:
        issues.append(
            LintIssue(
                path=path,
                message=(
                    "file is not canonically formatted; run "
                    f"`python tools/spec_yaml_format.py {path}`"
                ),
            )
        )
    return issues
